using System;using System.Globalization;using System.IO;using System.Text;
#nullable disable
public static class RebirthNpcProgressionAdministration
{
 public static string Inspect(RebirthNpcStableId id){var v=RebirthNpcProgressionProjectionService.Capture(id,true);var b=new StringBuilder();b.Append("[REBIRTH NPC Progression Inspect] npc=").Append(id).Append(" revision=").Append(v.Revision);foreach(var e in v.Entries)b.Append("\n  ").Append(e.Id).Append(" level=").Append(e.Level).Append('/').Append(e.MaximumLevel).Append(" xp=").Append(e.Xp).Append(" next=").Append(e.XpToNext);b.Append("\n  certifications=").Append(string.Join(",",v.Certifications));b.Append("\n  specializations=").Append(string.Join(",",v.Specializations));b.Append("\n  mentorships=").Append(string.Join(",",v.Mentorships));return b.ToString();}
 public static bool Export(RebirthNpcStableId id,out string path,out string detail){try{string d=Path.Combine(GameIO.GetSaveGameDir(),"RebirthNpcSupportExports");Directory.CreateDirectory(d);path=Path.Combine(d,"progression-"+id+"-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss",CultureInfo.InvariantCulture)+".txt");File.WriteAllText(path,Inspect(id)+"\n"+RebirthNpcProgressionTelemetry.Report()+"\n"+string.Join("\n",RebirthNpcProgressionTelemetry.Export()),new UTF8Encoding(false));detail="Progression diagnostic export written.";return true;}catch(Exception e){path="";detail=e.GetType().Name+": "+e.Message;return false;}}
 public static bool RepairSafeReset(RebirthNpcStableId id,out string detail){string path;if(!Export(id,out path,out detail))return false;bool a=RebirthNpcProgressionService.RemoveRecordForRepair(id);bool b=RebirthNpcAdvancedProgressionService.RemoveRecordForRepair(id);RebirthNpcProgressionPersistenceStore.MarkDirty();RebirthNpcAdvancedProgressionPersistenceStore.MarkDirty();RebirthNpcProgressionReplicationService.PublishDelta(id);detail="Reset completed after forensic export="+path+" coreRemoved="+a+" advancedRemoved="+b;return true;}
}
